use std::process::{Command, Stdio};
use std::time::Instant;
use std::io::Write;
use crate::cli::Config;

#[derive(Debug, Clone)]
pub struct BenchmarkResult {
    pub command: String,
    pub times: Vec<f64>,
    pub user_times: Vec<f64>,
    pub system_times: Vec<f64>,
    pub exit_codes: Vec<i32>,
}

pub fn run_benchmarks(config: &Config) -> Result<Vec<BenchmarkResult>, Box<dyn std::error::Error>> {
    let mut results = vec![];

    // Determine number of runs
    let num_runs = if let Some(runs) = config.exact_runs {
        runs
    } else {
        // Adaptive: run until we have at least min_runs and at least 3 seconds
        let mut runs = config.min_runs;
        if let Some(max) = config.max_runs {
            runs = runs.min(max);
        }
        runs
    };

    // Run setup command if provided
    if let Some(setup_cmd) = &config.setup_cmd {
        run_command(setup_cmd, config)?;
    }

    for (cmd_idx, cmd) in config.commands.iter().enumerate() {
        let prepare_cmd = if cmd_idx < config.prepare_cmds.len() && !config.prepare_cmds[cmd_idx].is_empty() {
            Some(config.prepare_cmds[cmd_idx].clone())
        } else if config.prepare_cmds.len() == 1 {
            Some(config.prepare_cmds[0].clone())
        } else {
            None
        };

        let conclude_cmd = if cmd_idx < config.conclude_cmds.len() && !config.conclude_cmds[cmd_idx].is_empty() {
            Some(config.conclude_cmds[cmd_idx].clone())
        } else if config.conclude_cmds.len() == 1 {
            Some(config.conclude_cmds[0].clone())
        } else {
            None
        };

        let cleanup_cmd = if cmd_idx < config.cleanup_cmds.len() && !config.cleanup_cmds[cmd_idx].is_empty() {
            Some(config.cleanup_cmds[cmd_idx].clone())
        } else if config.cleanup_cmds.len() == 1 {
            Some(config.cleanup_cmds[0].clone())
        } else {
            None
        };

        // Warmup runs
        for _ in 0..config.warmup_runs {
            if let Some(ref prep) = prepare_cmd {
                run_command(prep, config)?;
            }
            let _ = run_timed_command(cmd, config);
            if let Some(ref conc) = conclude_cmd {
                run_command(conc, config)?;
            }
        }

        // Actual benchmark runs
        let mut times = vec![];
        let mut user_times = vec![];
        let mut system_times = vec![];
        let mut exit_codes = vec![];

        for _ in 0..num_runs {
            if let Some(ref prep) = prepare_cmd {
                run_command(prep, config)?;
            }

            let (elapsed, user, system, exit_code) = run_timed_command(cmd, config)?;
            times.push(elapsed);
            user_times.push(user);
            system_times.push(system);
            exit_codes.push(exit_code);

            if let Some(ref conc) = conclude_cmd {
                run_command(conc, config)?;
            }
        }

        if let Some(ref cleanup) = cleanup_cmd {
            run_command(cleanup, config)?;
        }

        results.push(BenchmarkResult {
            command: cmd.clone(),
            times,
            user_times,
            system_times,
            exit_codes,
        });
    }

    Ok(results)
}

fn run_command(cmd: &str, config: &Config) -> Result<(), Box<dyn std::error::Error>> {
    let (program, args) = parse_command(cmd, config)?;

    let mut child = if config.show_output {
        Command::new(&program)
            .args(&args)
            .spawn()?
    } else {
        Command::new(&program)
            .args(&args)
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .spawn()?
    };

    let status = child.wait()?;

    if !status.success() && !config.ignore_failure {
        // Still continue, just track the exit code
    }

    Ok(())
}

fn run_timed_command(cmd: &str, config: &Config) -> Result<(f64, f64, f64, i32), Box<dyn std::error::Error>> {
    let (program, args) = parse_command(cmd, config)?;

    let start = Instant::now();
    let start_rusage = get_rusage();

    let mut child = if config.show_output {
        Command::new(&program)
            .args(&args)
            .spawn()?
    } else {
        Command::new(&program)
            .args(&args)
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .spawn()?
    };

    let status = child.wait()?;

    let end = Instant::now();
    let end_rusage = get_rusage();

    let elapsed = end.duration_since(start).as_secs_f64();
    let user = end_rusage.0 - start_rusage.0;
    let system = end_rusage.1 - start_rusage.1;

    let exit_code = status.code().unwrap_or(-1);

    Ok((elapsed, user, system, exit_code))
}

fn parse_command(cmd: &str, config: &Config) -> Result<(String, Vec<String>), Box<dyn std::error::Error>> {
    if config.shell == "none" {
        // Direct execution
        let parts: Vec<&str> = cmd.split_whitespace().collect();
        if parts.is_empty() {
            return Err("Empty command".into());
        }
        Ok((parts[0].to_string(), parts[1..].iter().map(|s| s.to_string()).collect()))
    } else {
        // Use shell
        let shell = get_shell(&config.shell)?;
        Ok((shell, vec!["-c".to_string(), cmd.to_string()]))
    }
}

fn get_shell(shell_spec: &str) -> Result<String, Box<dyn std::error::Error>> {
    if shell_spec == "default" {
        Ok("/bin/sh".to_string())
    } else if shell_spec.contains(' ') {
        // It's a full command line - we'll handle just the first part
        let parts: Vec<&str> = shell_spec.split_whitespace().collect();
        Ok(parts[0].to_string())
    } else {
        Ok(shell_spec.to_string())
    }
}

#[cfg(unix)]
fn get_rusage() -> (f64, f64) {
    use libc::getrusage;
    use std::mem;

    unsafe {
        let mut usage = mem::zeroed::<libc::rusage>();
        if getrusage(libc::RUSAGE_CHILDREN, &mut usage) == 0 {
            let user = usage.ru_utime.tv_sec as f64 + usage.ru_utime.tv_usec as f64 / 1_000_000.0;
            let system = usage.ru_stime.tv_sec as f64 + usage.ru_stime.tv_usec as f64 / 1_000_000.0;
            (user, system)
        } else {
            (0.0, 0.0)
        }
    }
}

#[cfg(not(unix))]
fn get_rusage() -> (f64, f64) {
    (0.0, 0.0)
}
