#[derive(Debug, Clone)]
pub struct Statistics {
    pub mean: f64,
    pub stddev: f64,
    pub median: f64,
    pub min: f64,
    pub max: f64,
    pub user_mean: f64,
    pub system_mean: f64,
}

pub fn compute_statistics(times: &[f64]) -> Statistics {
    if times.is_empty() {
        return Statistics {
            mean: 0.0,
            stddev: 0.0,
            median: 0.0,
            min: 0.0,
            max: 0.0,
            user_mean: 0.0,
            system_mean: 0.0,
        };
    }

    let mean = times.iter().sum::<f64>() / times.len() as f64;

    let variance = if times.len() > 1 {
        times.iter()
            .map(|t| (t - mean).powi(2))
            .sum::<f64>() / (times.len() - 1) as f64
    } else {
        0.0
    };

    let stddev = variance.sqrt();

    let mut sorted = times.to_vec();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap());

    let median = if sorted.len() % 2 == 0 {
        (sorted[sorted.len() / 2 - 1] + sorted[sorted.len() / 2]) / 2.0
    } else {
        sorted[sorted.len() / 2]
    };

    let min = sorted[0];
    let max = sorted[sorted.len() - 1];

    Statistics {
        mean,
        stddev,
        median,
        min,
        max,
        user_mean: 0.0,
        system_mean: 0.0,
    }
}
