pub fn to_json(results: &[BenchmarkResult], path: &str) -> Result<(), Box<dyn std::error::Error>> {
    let mut json_results = vec![];

    for result in results {
        let stats = statistics::compute_statistics(&result.times);
        json_results.push(json!({
            "command": result.command,
            "mean": stats.mean,
            "stddev": stats.stddev,
            "median": stats.median,
            "user": result.user_times.iter().sum::<f64>() / result.user_times.len().max(1) as f64,
            "system": result.system_times.iter().sum::<f64>() / result.system_times.len().max(1) as f64,
            "min": stats.min,
            "max": stats.max,
            "times": result.times,
            "memory_usage_byte": vec![0; result.times.len()],
            "exit_codes": result.exit_codes,
        }));
    }

    let output = json!({
        "results": json_results
    });

    let mut file = File::create(path)?;
