use std::env;

pub struct Args {
    pub commands: Vec<String>,
    pub warmup: Option<usize>,
    pub min_runs: usize,
    pub max_runs: Option<usize>,
    pub runs: Option<usize>,
    pub setup: Option<String>,
    pub reference: Option<String>,
    pub reference_name: Option<String>,
    pub prepare: Vec<String>,
    pub conclude: Vec<String>,
    pub cleanup: Vec<String>,
    pub parameter_scan: Option<Vec<String>>,
    pub parameter_step_size: Option<f64>,
    pub parameter_list: Vec<(String, String)>,
    pub shell: String,
    pub shell_none: bool,
    pub ignore_failure: Option<Option<String>>,
    pub style: String,
    pub sort: String,
    pub time_unit: Option<String>,
    pub export_asciidoc: Option<String>,
    pub export_csv: Option<String>,
    pub export_json: Option<String>,
    pub export_markdown: Option<String>,
    pub export_orgmode: Option<String>,
    pub show_output: bool,
    pub output: Option<String>,
    pub input: Option<String>,
    pub command_name: Vec<String>,
    pub show_help: bool,
    pub show_version: bool,
}

pub fn parse_args() -> Args {
    let args: Vec<String> = env::args().collect();
    let mut result = Args {
        commands: Vec::new(),
        warmup: None,
        min_runs: 10,
        max_runs: None,
        runs: None,
        setup: None,
        reference: None,
        reference_name: None,
        prepare: Vec::new(),
        conclude: Vec::new(),
        cleanup: Vec::new(),
        parameter_scan: None,
        parameter_step_size: None,
        parameter_list: Vec::new(),
        shell: "default".to_string(),
        shell_none: false,
        ignore_failure: None,
        style: "auto".to_string(),
        sort: "auto".to_string(),
        time_unit: None,
        export_asciidoc: None,
        export_csv: None,
        export_json: None,
        export_markdown: None,
        export_orgmode: None,
        show_output: false,
        output: None,
        input: None,
        command_name: Vec::new(),
        show_help: false,
        show_version: false,
    };

    let mut i = 1;
    while i < args.len() {
        let arg = &args[i];

        match arg.as_str() {
            "-h" | "--help" => result.show_help = true,
            "-V" | "--version" => result.show_version = true,
            "-w" | "--warmup" => {
                i += 1;
                if i < args.len() {
                    result.warmup = args[i].parse().ok();
                }
            }
            "-m" | "--min-runs" => {
                i += 1;
                if i < args.len() {
                    result.min_runs = args[i].parse().unwrap_or(10);
                }
            }
            "-M" | "--max-runs" => {
                i += 1;
                if i < args.len() {
                    result.max_runs = args[i].parse().ok();
                }
            }
            "-r" | "--runs" => {
                i += 1;
                if i < args.len() {
                    result.runs = args[i].parse().ok();
                }
            }
            "-s" | "--setup" => {
                i += 1;
                if i < args.len() {
                    result.setup = Some(args[i].clone());
                }
            }
            "--reference" => {
                i += 1;
                if i < args.len() {
                    result.reference = Some(args[i].clone());
                }
            }
            "--reference-name" => {
                i += 1;
                if i < args.len() {
                    result.reference_name = Some(args[i].clone());
                }
            }
            "-p" | "--prepare" => {
                i += 1;
                if i < args.len() {
                    result.prepare.push(args[i].clone());
                }
            }
            "-C" | "--conclude" => {
                i += 1;
                if i < args.len() {
                    result.conclude.push(args[i].clone());
                }
            }
            "-c" | "--cleanup" => {
                i += 1;
                if i < args.len() {
                    result.cleanup.push(args[i].clone());
                }
            }
            "-P" | "--parameter-scan" => {
                let mut params = Vec::new();
                for _ in 0..3 {
                    i += 1;
                    if i < args.len() {
                        params.push(args[i].clone());
                    }
                }
                if params.len() == 3 {
                    result.parameter_scan = Some(params);
                }
            }
            "-D" | "--parameter-step-size" => {
                i += 1;
                if i < args.len() {
                    result.parameter_step_size = args[i].parse().ok();
                }
            }
            "-L" | "--parameter-list" => {
