    if param_lists.is_empty() {
        return Ok(commands.to_vec());
    }

    let mut combinations = vec![];

    // Parse parameter lists
    let mut all_params: Vec<(String, Vec<String>)> = vec![];
    for (var, values) in param_lists {
        let value_list: Vec<String> = values.split(',').map(|s| s.to_string()).collect();
        all_params.push((var.clone(), value_list));
    }

    // Generate all combinations
    fn generate_combos(
        commands: &[String],
        params: &[(String, Vec<String>)],
        idx: usize,
        current: &mut HashMap<String, String>,
        results: &mut Vec<String>,
    ) {
        if idx == params.len() {
            for cmd in commands {
                let mut new_cmd = cmd.clone();
                for (var, val) in current.iter() {
