                if seconds < 0.005 {
                    (seconds * 1_000_000.0, "µs")
                } else if seconds < 1.0 {
                    (seconds * 1000.0, "ms")
                } else {
                    (seconds, "s")
                }
            }
        }
    } else {
        // Auto
        if seconds < 0.005 {
            (seconds * 1_000_000.0, "µs")
        } else if seconds < 1.0 {
            (seconds * 1000.0, "ms")
        } else {
            (seconds, "s")
        }
    };

    format!("{:.1} {}", value, suffix)
}
