// Simple JSON serialization without external dependencies

pub fn escape_string(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            _ => result.push(c),
        }
    }
    result
}

pub fn format_number(n: f64) -> String {
    format!("{}", n)
}

pub fn format_array_numbers(numbers: &[f64]) -> String {
    let mut result = String::from("[");
    for (i, n) in numbers.iter().enumerate() {
        if i > 0 {
            result.push(',');
        }
        result.push_str(&format_number(*n));
    }
    result.push(']');
    result
}

pub fn format_array_integers(numbers: &[i32]) -> String {
    let mut result = String::from("[");
    for (i, n) in numbers.iter().enumerate() {
        if i > 0 {
            result.push(',');
        }
        result.push_str(&n.to_string());
    }
    result.push(']');
    result
}
