        output.push_str(&format!("      \"stddev\": {},\n", stats.stddev));
        output.push_str(&format!("      \"median\": {},\n", stats.median));

        let user_mean = if result.user_times.is_empty() {
            0.0
        } else {
            result.user_times.iter().sum::<f64>() / result.user_times.len() as f64
        };
        let system_mean = if result.system_times.is_empty() {
