            let min_str = format_time(stats.min, &config.time_unit);
            let max_str = format_time(stats.max, &config.time_unit);
            println!("  Range (min … max):    {} …  {}    {} runs",
                     min_str, max_str, result.times.len());
        } else {
            let mean_str = format_time(stats.mean, &config.time_unit);
            let user_str = format_time(stats.user_mean, &config.time_unit);
            let system_str = format_time(stats.system_mean, &config.time_unit);
            println!("  Time (abs ≡):         {}               [User: {}, System: {}]",
                     mean_str, user_str, system_str);
        }

