        }

        println!();
    }

    // Print summary
    if results.len() > 1 {
        println!("Summary");

        // Find the fastest command (lowest mean time)
        let fastest_idx = results.iter()
            .enumerate()
            .min_by(|a, b| {
                let stats_a = statistics::compute_statistics(&a.1.times);
                let stats_b = statistics::compute_statistics(&b.1.times);
                stats_a.mean.partial_cmp(&stats_b.mean).unwrap_or(std::cmp::Ordering::Equal)
            })
            .map(|(i, _)| i)
            .unwrap_or(0);

        let fastest_stats = statistics::compute_statistics(&results[fastest_idx].times);

        for (i, result) in results.iter().enumerate() {
            if i == fastest_idx {
                continue;
            }

            let stats = statistics::compute_statistics(&result.times);
            let ratio = stats.mean / fastest_stats.mean;
            let ratio_err = (stats.stddev / fastest_stats.mean).sqrt() + (fastest_stats.stddev / fastest_stats.mean).sqrt();

            let cmd_name = if i < config.command_names.len() {
                config.command_names[i].clone()
            } else {
                config.commands[i].clone()
            };

            let fastest_name = if fastest_idx < config.command_names.len() {
                config.command_names[fastest_idx].clone()
            } else {
                config.commands[fastest_idx].clone()
            };

            if ratio_err.is_finite() && ratio_err > 0.0 {
                println!("  {} ran", fastest_name);
                println!("    {:.2} ± {:.2} times faster than {}", ratio, ratio_err, cmd_name);
            } else {
                println!("  {} ran", fastest_name);
                println!("    {:.2} times faster than {}", ratio, cmd_name);
            }
        }
    }

    Ok(())
}

fn format_time(seconds: f64, unit: &Option<String>) -> String {
    let unit = unit.as_deref();

    let (value, suffix) = if let Some(u) = unit {
        match u {
            "microsecond" | "microseconds" => (seconds * 1_000_000.0, "µs"),
            "millisecond" | "milliseconds" => (seconds * 1000.0, "ms"),
            "second" | "seconds" => (seconds, "s"),
            _ => {
                // Auto
                if seconds < 0.005 {
                    (seconds * 1_000_000.0, "µs")
                } else if seconds < 1.0 {
                    (seconds * 1000.0, "ms")
                } else {
                    (seconds, "s")
                }
            }
        }
    } else {
        // Auto
        if seconds < 0.005 {
            (seconds * 1_000_000.0, "µs")
        } else if seconds < 1.0 {
            (seconds * 1000.0, "ms")
        } else {
            (seconds, "s")
        }
    };

    format!("{:.1} {}", value, suffix)
}
