    pub ignore_failure_codes: Vec<i32>,
    pub style: String,
    pub sort: String,
}

pub fn run(args: &args::Args) -> Result<(), Box<dyn std::error::Error>> {
    let mut config = Config {
        commands: args.commands.clone(),
        command_names: args.command_name.clone(),
        warmup_runs: args.warmup.unwrap_or(0),
        min_runs: args.min_runs,
        max_runs: args.max_runs,
        exact_runs: args.runs,
        setup_cmd: args.setup.clone(),
        prepare_cmds: args.prepare.clone(),
        conclude_cmds: args.conclude.clone(),
        cleanup_cmds: args.cleanup.clone(),
        shell: if args.shell_none { "none".to_string() } else { args.shell.clone() },
        show_output: args.show_output,
        output_mode: args.output.clone().unwrap_or_else(|| "null".to_string()),
        input_mode: args.input.clone().unwrap_or_else(|| "null".to_string()),
        time_unit: args.time_unit.clone(),
        ignore_failure: args.ignore_failure.is_some(),
        ignore_failure_codes: parse_ignore_failure(&args.ignore_failure),
        style: args.style.clone(),
        sort: args.sort.clone(),
    };

    // Handle parameter scanning
    let mut commands_to_run = vec![];

    if let Some(params) = &args.parameter_scan {
        if params.len() != 3 {
            return Err("parameter-scan requires VAR, MIN, MAX".into());
        }
        let var_name = &params[0];
        let min_val: f64 = params[1].parse()?;
        let max_val: f64 = params[2].parse()?;
        let step = args.parameter_step_size.unwrap_or(1.0);

        let mut val = min_val;
        while val <= max_val + 1e-9 {
            for cmd in &config.commands {
                let new_cmd = cmd.replace(&format!("{{{}}}", var_name), &format_param(val));
                commands_to_run.push(new_cmd);
            }
            val += step;
        }
    } else if !args.parameter_list.is_empty() {
        // Handle parameter list combinations
        commands_to_run = generate_parameter_list_commands(&config.commands, &args.parameter_list)?;
    } else {
        commands_to_run = config.commands.clone();
    }

    config.commands = commands_to_run;

    // Pad command names if needed
    while config.command_names.len() < config.commands.len() {
        config.command_names.push(format!("{}", config.commands[config.command_names.len()]));
    }

    // Run benchmarks
    let results = benchmarking::run_benchmarks(&config)?;

    // Print results
    print_results(&config, &results)?;

    // Export results if requested
    if let Some(path) = &args.export_json {
        export::to_json(&results, path)?;
    }
    if let Some(path) = &args.export_markdown {
        export::to_markdown(&config, &results, path)?;
    }
    if let Some(path) = &args.export_csv {
        export::to_csv(&results, path)?;
    }
    if let Some(path) = &args.export_asciidoc {
        export::to_asciidoc(&config, &results, path)?;
    }
    if let Some(path) = &args.export_orgmode {
        export::to_orgmode(&config, &results, path)?;
    }

    Ok(())
}

fn parse_ignore_failure(ignore_failure: &Option<Option<String>>) -> Vec<i32> {
    match ignore_failure {
        Some(Some(codes)) => {
            codes.split(',')
                .filter_map(|c| c.trim().parse().ok())
                .collect()
        }
        Some(None) => vec![], // all non-zero
        None => vec![],
    }
}

fn format_param(val: f64) -> String {
    if val.fract() == 0.0 {
        format!("{}", val as i64)
    } else {
        format!("{}", val)
    }
}

fn generate_parameter_list_commands(
    commands: &[String],
    param_lists: &[(String, String)],
) -> Result<Vec<String>, Box<dyn std::error::Error>> {
    if param_lists.is_empty() {
        return Ok(commands.to_vec());
    }

    let mut combinations = vec![];

    // Parse parameter lists
    let mut all_params: Vec<(String, Vec<String>)> = vec![];
    for (var, values) in param_lists {
        let value_list: Vec<String> = values.split(',').map(|s| s.to_string()).collect();
        all_params.push((var.clone(), value_list));
    }

    // Generate all combinations
    fn generate_combos(
        commands: &[String],
        params: &[(String, Vec<String>)],
        idx: usize,
        current: &mut HashMap<String, String>,
        results: &mut Vec<String>,
    ) {
        if idx == params.len() {
            for cmd in commands {
                let mut new_cmd = cmd.clone();
                for (var, val) in current.iter() {
                    new_cmd = new_cmd.replace(&format!("{{{}}}", var), val);
                }
                results.push(new_cmd);
            }
            return;
        }

        for val in &params[idx].1 {
            current.insert(params[idx].0.clone(), val.clone());
            generate_combos(commands, params, idx + 1, current, results);
            current.remove(&params[idx].0);
        }
    }

    let mut current = HashMap::new();
    generate_combos(commands, &all_params, 0, &mut current, &mut combinations);

    Ok(combinations)
}

